recipes.code:
{
  "inputs": [
    {
      "id": "borough-api-key",
      "type": "promptString",
      "description": "Your Borough API key (get one free at https://borough.qwady.app/pricing)",
      "password": true
    }
  ],
  "servers": {
    "borough": {
      "type": "stdio",
      "command": "npx",
      "args": [
        "-y",
        "@borough/mcp@1.1.0"
      ],
      "env": {
        "BOROUGH_API_KEY": "${input:borough-api-key}"
      }
    }
  }
}
